import "server-only";
import Anthropic from "@anthropic-ai/sdk";
import { z, type ZodSchema } from "zod";

// Routes all non-grounded agent calls through the Anthropic API using a token
// generated by `claude setup-token`. That token is billed against your Max
// subscription (free up to the monthly cap). Falls back to a standard API key
// if you set ANTHROPIC_API_KEY directly.
//
// Why not the Agent SDK? It spawns the `claude` CLI as a subprocess. That CLI
// needs interactive auth via `claude auth login`, and even when authed it adds
// 2-5s of subprocess startup per call. The direct SDK is faster and uses the
// same long-lived OAuth tokens.

const MODEL = "claude-sonnet-4-5";

function getClient(): Anthropic {
  const key = process.env.ANTHROPIC_API_KEY;
  if (!key) {
    throw new Error(
      "ANTHROPIC_API_KEY missing. Run `claude setup-token` in your terminal, then add the resulting token to .env.local.",
    );
  }
  // Anthropic's SDK accepts OAuth tokens (sk-ant-oat01-...) and API keys
  // (sk-ant-api03-...) interchangeably as the `apiKey` field. Both bill
  // correctly — OAuth tokens against your Max sub, API keys against console.
  return new Anthropic({ apiKey: key });
}

// ---- generateText: one-shot, returns final string ----------------------------

export async function generateText({
  system,
  prompt,
  model = MODEL,
  temperature,
  maxTokens = 8192,
}: {
  system?: string;
  prompt: string;
  model?: string;
  temperature?: number;
  maxTokens?: number;
}): Promise<{ text: string }> {
  const client = getClient();
  const response = await client.messages.create({
    model,
    max_tokens: maxTokens,
    temperature,
    system,
    messages: [{ role: "user", content: prompt }],
  });

  // Concatenate any text blocks (in practice always 1 for non-tool calls).
  const text = response.content
    .filter((b): b is Anthropic.TextBlock => b.type === "text")
    .map((b) => b.text)
    .join("");

  if (!text) {
    throw new Error(
      `Claude returned no text content. stop_reason=${response.stop_reason}`,
    );
  }
  return { text };
}

// ---- streamText: async iterable of text deltas -------------------------------

export async function* streamText({
  system,
  prompt,
  model = MODEL,
  temperature,
  maxTokens = 8192,
}: {
  system?: string;
  prompt: string;
  model?: string;
  temperature?: number;
  maxTokens?: number;
}): AsyncGenerator<string, void, void> {
  const client = getClient();
  const stream = await client.messages.stream({
    model,
    max_tokens: maxTokens,
    temperature,
    system,
    messages: [{ role: "user", content: prompt }],
  });

  // Anthropic SDK's `.stream()` returns an EventEmitter-like object with
  // async iteration of `text` events. We yield each delta as a string.
  for await (const event of stream) {
    if (
      event.type === "content_block_delta" &&
      event.delta.type === "text_delta"
    ) {
      yield event.delta.text;
    }
  }
}

// ---- generateObject: prompt the model for JSON, validate with Zod ------------

export async function generateObject<T>({
  schema,
  system,
  prompt,
  model = MODEL,
  temperature = 0.3,
}: {
  schema: ZodSchema<T>;
  system?: string;
  prompt: string;
  model?: string;
  temperature?: number;
}): Promise<{ object: T }> {
  // Append schema instruction to the system prompt so the model knows the shape.
  const fullSystem = [
    system ?? "",
    "Return ONLY a valid JSON object matching the requested shape.",
    "No markdown code fences. No prose before or after. Just JSON.",
  ]
    .filter(Boolean)
    .join("\n\n");

  const { text } = await generateText({
    system: fullSystem,
    prompt,
    model,
    temperature,
  });

  // Strip ```json fences if Claude adds them anyway
  const cleaned = text
    .replace(/^```(?:json)?\s*\n?/i, "")
    .replace(/\n?```\s*$/i, "")
    .trim();

  let parsed: unknown;
  try {
    parsed = JSON.parse(cleaned);
  } catch (err) {
    throw new Error(
      `Claude returned non-JSON output: ${cleaned.slice(0, 200)}... (${err instanceof Error ? err.message : "unknown"})`,
    );
  }

  const result = schema.safeParse(parsed);
  if (!result.success) {
    throw new Error(
      `Claude output failed schema validation: ${result.error.message}`,
    );
  }

  return { object: result.data };
}

export { z };
